package com.mutqin.app

data class HadithEntry(
  val id: Int, val title: String, val text: String, val narrator: String,
  val source: String, val reference: String, val grade: String, val explanation: String
)

val hadithEntries = listOf(
  HadithEntry(1,"الأعمال بالنيات","إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى.","عمر بن الخطاب رضي الله عنه","صحيح البخاري وصحيح مسلم","البخاري 1؛ مسلم 1907","صحيح؛ متفق عليه","يبين الحديث أثر النية في الأعمال، وأن قصد القلب معتبر في الثواب وصحة كثير من الأعمال. ولا يعني أن النية وحدها تغني عن أداء العمل على وجهه الصحيح."),
  HadithEntry(2,"أركان الإسلام الخمسة","بُنِيَ الإِسْلَامُ عَلَى خَمْسٍ: شَهَادَةِ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَإِقَامِ الصَّلَاةِ، وَإِيتَاءِ الزَّكَاةِ، وَالْحَجِّ، وَصَوْمِ رَمَضَانَ.","عبد الله بن عمر رضي الله عنهما","صحيح البخاري وصحيح مسلم","البخاري 8؛ مسلم 16","صحيح؛ متفق عليه","يجمع الحديث أركان الإسلام الظاهرة الخمسة، ويبين مكانة الشهادتين والصلاة والزكاة والصوم والحج."),
  HadithEntry(3,"الدين النصيحة","الدِّينُ النَّصِيحَةُ. قُلْنَا: لِمَنْ؟ قَالَ: لِلَّهِ، وَلِكِتَابِهِ، وَلِرَسُولِهِ، وَلِأَئِمَّةِ الْمُسْلِمِينَ وَعَامَّتِهِمْ.","تميم الداري رضي الله عنه","صحيح مسلم","مسلم 55a","صحيح","النصيحة إخلاص وصدق وإرادة الخير، وتكون لله تعالى واتباع كتابه ورسوله وإرادة الخير للمسلمين بالحكمة والرفق."),
  HadithEntry(4,"الكلمة الطيبة وحفظ اللسان","مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ.","أبو هريرة رضي الله عنه","صحيح مسلم","مسلم 47a؛ وله روايات في الصحيحين","صحيح","يرشد الحديث إلى انتقاء الكلام النافع، وترك القول المؤذي أو الذي لا خير فيه، ويذكر في الرواية نفسها إكرام الجار والضيف."),
  HadithEntry(5,"محبة الخير للآخرين","لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ.","أنس بن مالك رضي الله عنه","صحيح البخاري وصحيح مسلم","البخاري 13؛ مسلم 45","صحيح؛ متفق عليه","يدعو الحديث إلى سلامة الصدر ومحبة الخير للناس، وترك الأنانية والحسد، وهو من كمال الإيمان الواجب.")
)

data class FiqhEntry(
  val id: Int, val title: String, val question: String, val ruling: String,
  val evidence: String, val explanation: String, val scope: String, val references: String
)

val fiqhEntries = listOf(
  FiqhEntry(1,"أصل الوضوء","ما الأعضاء المذكورة في آية الوضوء؟","ذكرت آية الوضوء غسل الوجه واليدين إلى المرافق، ومسح الرأس، وغسل الرجلين إلى الكعبين.","القرآن الكريم، سورة المائدة 5:6.","هذه خلاصة للأعضاء الواردة في الآية، أما صفة الوضوء الكاملة وسننه ونواقضه فتدرس بأدلتها وأقوال أهل العلم.","تعليمي عام؛ لا يتناول تفاصيل الخلاف في بعض جزئيات الصفة.","سورة المائدة: 6؛ صحيح البخاري، كتاب الوضوء."),
  FiqhEntry(2,"الصلاة المفروضة","ما أصل فرض الصلوات المكتوبة؟","الصلاة المكتوبة فريضة على المسلمين، وقد أمر القرآن بالمحافظة عليها وبيّن أن لها أوقاتًا محددة.","القرآن الكريم، سورة النساء 4:103؛ وحديث أركان الإسلام، البخاري 8 ومسلم 16.","يتعلم المسلم أسماء الصلوات وأوقاتها وشروطها وأركانها من مصادر الفقه المعتمدة، ولا تكفي هذه البطاقة وحدها لتعليم صفة الصلاة كاملة.","مدخل عام؛ تفاصيل الأعذار والجمع والقصر لها أبواب مستقلة.","سورة النساء: 103؛ صحيح البخاري 8؛ صحيح مسلم 16."),
  FiqhEntry(3,"التيمم عند العذر","متى يشرع التيمم إجمالًا؟","شرع القرآن التيمم عند فقد الماء أو وجود عذر معتبر يمنع استعماله، ويكون بصعيد طيب مع مسح الوجه واليدين وفق الآية.","القرآن الكريم، سورة المائدة 5:6؛ وسورة النساء 4:43.","للتيمم شروط وتفاصيل تتعلق بالعذر والصعيد والكيفية ونواقضه، وتختلف بعض الجزئيات بين المذاهب؛ فيرجع فيها إلى عالم موثوق.","بيان أصل الحكم فقط؛ لا يقرر جميع صور الأعذار أو تفاصيل المذاهب.","سورة المائدة: 6؛ سورة النساء: 43؛ صحيح البخاري، كتاب التيمم."),
  FiqhEntry(4,"فرض صيام رمضان","ما أصل وجوب صيام رمضان؟","فرض الله صيام شهر رمضان على المؤمنين، وذكر أحكام المريض والمسافر في آيات الصيام.","القرآن الكريم، سورة البقرة 2:183-185.","هذه البطاقة تثبت أصل الفرض ولا تفصل أحكام القضاء والفدية والمرض والسفر والبلوغ؛ فلكل منها شروط وتفصيل فقهي.","مدخل عام؛ الحالات الخاصة تحتاج سؤال أهل العلم مع بيان الحالة.","سورة البقرة: 183-185؛ صحيح البخاري، كتاب الصوم."),
  FiqhEntry(5,"الطهارة للصلاة","ما الدليل على الوضوء للصلاة عند الحدث؟","دلت السنة على أن من أحدث لا يصلي حتى يتوضأ، مع مراعاة أحكام الطهارة وأعذارها.","حديث: لا يقبل الله صلاة أحدكم إذا أحدث حتى يتوضأ؛ صحيح البخاري 135 وصحيح مسلم 225.","الحدث ونواقض الوضوء وأحكام أصحاب الأعذار مسائل لها تفصيل، وهذه البطاقة تذكر أصل الارتباط بين الطهارة والصلاة فقط.","قاعدة عامة؛ لا تستوعب الخلاف في النواقض أو أحوال العذر.","صحيح البخاري 135؛ صحيح مسلم 225؛ سورة المائدة: 6.")
)

data class QuranStory(
  val id: Int, val title: String, val summary: String, val verses: String,
  val lessons: List<String>, val sourceNote: String
)

val quranStories = listOf(
  QuranStory(1,"قصة يوسف عليه السلام","يعرض القرآن رؤيا يوسف، ومحنته مع إخوته، وانتقاله إلى مصر، وابتلاءه في السجن، ثم تمكين الله له واجتماع أسرته.","سورة يوسف: 4-101.",listOf("الصبر عند الشدائد","العفة والأمانة","العفو عند المقدرة","حسن الظن بتدبير الله"),"الملخص مستخرج من تسلسل الآيات؛ لا تضاف تفاصيل القصاص والروايات غير المذكورة في القرآن إلا بعد تخريجها."),
  QuranStory(2,"قصة نوح عليه السلام","يذكر القرآن دعوة نوح لقومه، وإصراره على دعوتهم، وموقف المكذبين، ثم أمر الله بصنع الفلك ونجاة المؤمنين.","سورة هود: 25-49؛ وانظر سورة نوح: 1-28.",listOf("الصبر في الدعوة","التوكل على الله","أن النجاة بالإيمان لا بمجرد القرابة","العبرة بعاقبة التكذيب"),"يعتمد العرض على الآيات المحددة، مع تجنب تحديد أمور لم يحددها النص القرآني."),
  QuranStory(3,"قصة إبراهيم عليه السلام وتحطيم الأصنام","يحاور إبراهيم قومه في عبادة الأصنام، ويقيم عليهم الحجة، ثم يواجه موقفهم بعد تحطيم الأصنام وينجيه الله من كيدهم.","سورة الأنبياء: 51-70؛ وانظر سورة الأنعام: 74-83.",listOf("إفراد الله بالعبادة","التفكر والاستدلال","الثبات على الحق","التوكل على الله"),"تسلسل القصة مأخوذ من القرآن الكريم؛ لا تُضاف حوارات أو تفاصيل تاريخية غير موثقة."),
  QuranStory(4,"قصة موسى عليه السلام","تتناول الآيات نداء الله لموسى، وإرساله إلى فرعون، وآياته، ومواجهة السحرة، وما جرى لبني إسرائيل في مقاطع متعددة من السورة.","سورة طه: 9-98؛ وتوجد مقاطع أخرى في سور القصص والأعراف والشعراء.",listOf("الثقة بالله عند التكليف","مواجهة الظلم بالحجة","أن النصر من عند الله","أهمية الصبر والذكر"),"هذه بطاقة تمهيدية لمقاطع من القصة وليست سردًا شاملًا لجميع أحداث موسى عليه السلام."),
  QuranStory(5,"أصحاب الكهف","يذكر القرآن فتية آمنوا بربهم واعتزلوا قومهم، فآواهم الله إلى الكهف، ثم بعثهم ليظهر أمرهم آية للناس.","سورة الكهف: 9-26.",listOf("الثبات على الإيمان","صحبة الصالحين","طلب رحمة الله والهداية","أن علم الغيب الكامل لله"),"يلتزم الملخص بما ورد في الآيات، ولا يجزم بأسمائهم أو عددهم أو زمنهم إلا بدليل صحيح.")
)
